using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF Core 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so preserve the old property name.
            entity.HasDiscriminator().HasJsonPropertyName("Discriminator");

            // Breaking change 2: EF Core 9 uses only the raw key for the "id" property.
            // Existing documents have id = "Blog|1", so restore the old format.
            entity.HasIdProperty(e => e.Id, useDiscriminatorPrefix: true);

            // Breaking change 3: EF Core 9 no longer supports indexes on Cosmos DB
            // (they were silently ignored before). Removed HasIndex call.
        });
    }
}
