using System.Linq;

class SyncJob
{
    void Run(BlogContext context)
    {
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
    }

    // Breaking change 4: Raw SQL queries referencing "Discriminator" continue to work
    // because we configured HasDiscriminator<string>("Discriminator") above.
    // Without that fix, you'd need to change queries from:
    //   SELECT * FROM c WHERE c.Discriminator = 'Blog'
    // to:
    //   SELECT * FROM c WHERE c["$type"] = 'Blog'
}

